import{_ as s,a0 as a,w as p,s as u,I as r,x as l,a1 as i,A as o,ao as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"管理對新手友好的開源社區的三個步驟 | LCTT x X-CMD","titleTemplate":false,"description":"管理對新手友好的開源社區的三個步驟 | LCTT (202302) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"管理對新手友好的開源社區的三個步驟 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"管理對新手友好的開源社區的三個步驟 | LCTT (202302) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202302/20210820 3 steps for managing a beginner-friendly open source community","title":"管理對新手友好的開源社區的三個步驟","tag":"202302","desc":""},"relativePath":"202302/20210820 3 steps for managing a beginner-friendly open source community.md","filePath":"[post].md"}'),d={name:"202302/20210820 3 steps for managing a beginner-friendly open source community.md"};function m(f,t,b,g,T,x){const n=a("Link");return p(),u("div",null,[t[47]||(t[47]=r("h1",{id:"管理對新手友好的開源社區的三個步驟",tabindex:"-1"},[l("管理對新手友好的開源社區的三個步驟 "),r("a",{class:"header-anchor",href:"#管理對新手友好的開源社區的三個步驟","aria-label":"Permalink to “管理對新手友好的開源社區的三個步驟”"},"​")],-1)),t[48]||(t[48]=r("blockquote",null,[r("p",null,"作為一個開源項目的成員，你可以做很多事情來幫助新手找到為項目作出貢獻的方式。")],-1)),t[49]||(t[49]=r("p",null,[r("img",{src:"https://img.linux.net.cn/data/attachment/album/202302/12/222832vxfof8844fo4vsl4.jpg",alt:""})],-1)),t[50]||(t[50]=r("p",null,"當有人剛開始為開源做貢獻時，最好從對新手友好的故障和議題開始。但在他們修復故障之前，他們必須要能夠找到這類問題。作為一個開源項目的成員，你可以做很多事情來幫助新手找到為項目貢獻的方式。",-1)),r("p",null,[t[1]||(t[1]=l("鑑於此，",-1)),i(n,{href:"https://github.com/anitab-org"},{default:o(()=>[...t[0]||(t[0]=[l("AnitaB.org 開源社區",-1)])]),_:1}),t[2]||(t[2]=l(" 優先考慮讓我們的社區做到對新手友好。我們提倡包容性，確保不同經驗和水平的貢獻者都可以參與進來，並且他們的貢獻不止限於跟編程有關。",-1))]),r("p",null,[t[5]||(t[5]=l("我最近在 ",-1)),i(n,{href:"https://youtu.be/l8r50jCr-Yo"},{default:o(()=>[...t[3]||(t[3]=[l("Upstream 2021",-1)])]),_:1}),t[6]||(t[6]=l("，即 Tidelift 活動中介紹了我們在 ",-1)),i(n,{href:"https://anitab.org/"},{default:o(()=>[...t[4]||(t[4]=[l("AnitaB.org",-1)])]),_:1}),t[7]||(t[7]=l(" 上所做的一些社區工作，該活動啓動了“維護者周”，這是一個為期一週的開源維護者慶祝活動。在活動中我討論了我們策略的三個主要部分：",-1))]),t[51]||(t[51]=e('<ul><li>我們如何溝通</li><li>項目和議題</li><li>開源項目</li></ul><h3 id="我們如何溝通" tabindex="-1">我們如何溝通 <a class="header-anchor" href="#我們如何溝通" aria-label="Permalink to “我們如何溝通”">​</a></h3><p>透明度是開源的重要組成部分，我們將透明度原則應用於我們的溝通方式。實際上，這意味着我們所有的社區會議都是公開進行的，並且影響我們設置 Zulip 聊天的方式以及我們提供文檔的方式。</p><h4 id="開放會議" tabindex="-1">開放會議 <a class="header-anchor" href="#開放會議" aria-label="Permalink to “開放會議”">​</a></h4><p>任何人都可以加入我們的會議，並討論與我們社區相關的話題。他們可以參與討論或者旁聽。會議相關信息在我們的社區日曆中都可以找到。在這些通話中我們通常只使用語音聊天，我們發現這可以讓人們在參與時感覺更自在。</p><p>我們舉辦以項目為中心的會議和一些分類的會議。會議上，來自不同領域的人們可以討論同一個項目並幫助改進我們的流程。偶爾，我們會有“<ruby>自由提問<rt>Ask Me Anything</rt></ruby>（AMA）”會議，任何人都可以來問任何與開源相關的問題。</p>',6)),r("p",null,[t[9]||(t[9]=l("所有會議我們都會在共享文檔中進行記錄，並在 ",-1)),i(n,{href:"https://anitab-org.zulipchat.com/"},{default:o(()=>[...t[8]||(t[8]=[l("我們的 Zulip",-1)])]),_:1}),t[10]||(t[10]=l(" 中共享摘要和文檔鏈接。",-1))]),t[52]||(t[52]=e('<h4 id="我們的-zulip-聊天" tabindex="-1">我們的 Zulip 聊天 <a class="header-anchor" href="#我們的-zulip-聊天" aria-label="Permalink to “我們的 Zulip 聊天”">​</a></h4><p>開源 Zulip 聊天平台是我們的主要社區交流渠道，雖然我們也在 Github 的評論區討論議題和<ruby>拉取請求<rt>Pull Request</rt></ruby>（PR）。一般來説，我們禁用了私人消息以確保我們儘可能透明。對於這條規則，我們只有少數例外，那些私人聊天是管理員在處理我們運行程序的後勤工作所用的。我們發現這種方法更受歡迎，它還使我們能夠更清楚公共聊天中的違規行為。</p><p>我們在 Zulip 聊天室分享所有會議摘要，包括討論的要點、行動項目和文檔。這些聽起來好像是些顯而易見的要求，但我一直驚訝於很多開源項目並不提供會議筆記，所以 Zulip 可以讓那些沒有參加會議的人也隨時瞭解情況。</p><p>在 Zulip上，我們討論項目路線圖，回答社區的問題和疑問，並積極<strong>促進人們通過不同的方式方法和在不同的場景下做出自己的貢獻</strong>。有時我們為貢獻者的成就而慶祝 —— 無論是為了突出他們測試或者審查的第一個拉取請求，還是強調我們志願者所做的出色工作。</p><h4 id="文檔" tabindex="-1">文檔 <a class="header-anchor" href="#文檔" aria-label="Permalink to “文檔”">​</a></h4><p>我們儘量保持<strong>關於我們流程的開放文檔</strong>，例如常見問題解答，以便這些社區成員可以按照自己的節奏和時間瞭解社區。這是為了讓他們在聯繫我們之前瞭解我們的工作方式以及我們從事的工作類型。</p><h3 id="項目和議題" tabindex="-1">項目和議題 <a class="header-anchor" href="#項目和議題" aria-label="Permalink to “項目和議題”">​</a></h3><p>關於我們的項目和議題管理，我們鼓勵通過多種方式做出貢獻，我們為新手專門創建特定的議題，並嘗試讓項目的設置變得簡單。</p><h4 id="多種貢獻的方式" tabindex="-1">多種貢獻的方式 <a class="header-anchor" href="#多種貢獻的方式" aria-label="Permalink to “多種貢獻的方式”">​</a></h4><p>我們努力創建<strong>需要不同貢獻的問題</strong>，例如文檔、測試、設計和外展。這是為了讓任何人 —— 無關他們的經驗水平和興趣領域 —— 都能做出貢獻。這樣能夠幫助社區參與進來，而且我們發現它使成員能夠從一些省力但有價值的任務開始一步步做出貢獻。</p><p>我們提倡的貢獻類型有：</p><ul><li>不同複雜性的編程任務。</li><li>質量保證任務 —— 貢獻者可以測試我們的應用程序或拉取請求並報告錯誤。</li><li>社區成員可以參與討論的設計會議。此外，創建模型和重新設計我們應用程序某些部分的機會，並探索改進用户體驗。</li><li>外展任務，我們主要在 Zulip 上推廣，我們建議在我們的 Medium 出版物上發表Blog，介紹他們的開源經驗和他們的貢獻。</li><li>文檔任務，可以包括一般社區文檔或我們在 Docusaurus 上的項目文檔。</li></ul><h4 id="僅限新手的問題" tabindex="-1">僅限新手的問題 <a class="header-anchor" href="#僅限新手的問題" aria-label="Permalink to “僅限新手的問題”">​</a></h4>',13)),r("p",null,[t[12]||(t[12]=l("我們將一些",-1)),t[13]||(t[13]=r("strong",null,"議題標記為“僅限新手”",-1)),t[14]||(t[14]=l("。這些問題適用於尚未為議題存儲庫做出貢獻的人。為議題做標籤還使我們能夠讓人們在貢獻者大量湧入時開始他們的開源之旅，例如，在 ",-1)),i(n,{href:"https://summerofcode.withgoogle.com/"},{default:o(()=>[...t[11]||(t[11]=[l("谷歌編程之夏（GSoC）",-1)])]),_:1}),t[15]||(t[15]=l(" 申請期間。",-1))]),t[53]||(t[53]=r("p",null,"有時，這些可能是“唾手可得的果實”，可以讓他們熟悉作出貢獻和提交拉取請求的過程。",-1)),t[54]||(t[54]=r("h4",{id:"簡單的項目設置",tabindex:"-1"},[l("簡單的項目設置 "),r("a",{class:"header-anchor",href:"#簡單的項目設置","aria-label":"Permalink to “簡單的項目設置”"},"​")],-1)),t[55]||(t[55]=r("p",null,[l("我們也很在意為我們的項目提供"),r("strong",null,"新手友好的安裝設置"),l("。我們注意到最活躍的項目通常是最容易設置的。我們知道，為你不熟悉的項目做出貢獻可能需要付出很多努力並且關乎貢獻體驗的成敗。")],-1)),t[56]||(t[56]=r("p",null,"我們嘗試提供有關如何在多個操作系統上運行我們項目的説明。在過去，我們有一些項目有單獨的説明，可以在 Unix 環境下運行，我們注意到貢獻者在 Windows 上運行這些項目有些困難。自那以後我們不斷進行改進，以避免貢獻者在 Zulip 上尋求幫助時出現混亂。",-1)),r("p",null,[t[18]||(t[18]=l("我們根據貢獻者的經驗，一直在改進我們最活躍的項目之一 ",-1)),i(n,{href:"https://github.com/anitab-org/mentorship-backend#readme"},{default:o(()=>[...t[16]||(t[16]=[l("mentorship-backend",-1)])]),_:1}),t[19]||(t[19]=l(" 的自述文件。新手在這個項目中遇到的困難之一是設置與配置電子郵件帳户相關的部分環境變量，以使後台功能能夠發送電子郵件。但是，由於此功能對於本地開發並不重要，因此默認情況下，我們將電子郵件設置設為可選，以便將電子郵件打印到終端，而不是發送給用户。這種方法仍然使貢獻者可以看到這些電子郵件。與此更改類似，我們將 ",-1)),i(n,{href:"https://opensource.com/article/21/2/sqlite3-cheat-sheet"},{default:o(()=>[...t[17]||(t[17]=[l("SQLite 資料庫",-1)])]),_:1}),t[20]||(t[20]=l(" 作為本地開發的默認設置，以避免對 Postgres 資料庫進行額外設置，雖然我們在部署版本中會使用到 Postgres。",-1))]),r("p",null,[t[23]||(t[23]=l("我們注意到，一些貢獻者在為我們的 ",-1)),i(n,{href:"https://github.com/anitab-org/bridge-in-tech-backend"},{default:o(()=>[...t[21]||(t[21]=[l("bridge-in-tech-backend",-1)])]),_:1}),t[24]||(t[24]=l(" 項目做出貢獻時覺得很困難，該項目的設置很複雜，並且包含的步驟比 ",-1)),i(n,{href:"https://github.com/anitab-org/mentorship-backend#readme"},{default:o(()=>[...t[22]||(t[22]=[l("mentorship-backend",-1)])]),_:1}),t[25]||(t[25]=l(" 多得多。自從我們在一個開源項目中注意到這一點以來，我們一直在探索如何改進其結構。",-1))]),r("p",null,[t[27]||(t[27]=l("對於我們的大多數項目，我們還提供應用程序的實時體驗版本或打包版本，以便貢獻者無需設置即可測試項目。這有助於我們為那些對開發設置不感興趣或不熟悉的貢獻者提供一種方式，來嘗試我們應用程序的最新版本，並通過報告發現的任何錯誤來做出貢獻。我們在 ",-1)),i(n,{href:"https://github.com/anitab-org/documentation/blob/master/quality-assurance.md"},{default:o(()=>[...t[26]||(t[26]=[l("質量保證指南",-1)])]),_:1}),t[28]||(t[28]=l(" 中放了這些應用程序的鏈接。",-1))]),t[57]||(t[57]=r("h3",{id:"開源計劃",tabindex:"-1"},[l("開源計劃 "),r("a",{class:"header-anchor",href:"#開源計劃","aria-label":"Permalink to “開源計劃”"},"​")],-1)),t[58]||(t[58]=r("p",null,"我們在社區中組織了兩個主要計劃：開源黑客（OSH）（一個為期一個月的項目）和 Open Source Ambassadors（一個為期六個月的項目）。",-1)),t[59]||(t[59]=r("h4",{id:"開源黑客-osh",tabindex:"-1"},[l("開源黑客（OSH） "),r("a",{class:"header-anchor",href:"#開源黑客-osh","aria-label":"Permalink to “開源黑客（OSH）”"},"​")],-1)),r("p",null,[t[30]||(t[30]=l("在此計劃中，我們在多個類別的貢獻中創建議題 —— 文檔、編碼、外展、測試和設計（類似於 ",-1)),i(n,{href:"https://codein.withgoogle.com/"},{default:o(()=>[...t[29]||(t[29]=[l("谷歌的 Code-in",-1)])]),_:1}),t[31]||(t[31]=l(" 競賽）。 參與者可以為每個類別至少貢獻一次並獲得電子證書。一個議題可能包含多個類別，並且無需合併拉取請求也能使貢獻有效。",-1))]),t[60]||(t[60]=e('<p>我們為這個計劃選取幾個項目，請導師們集思廣益為參與者創造議題。項目開始後參與者可以認領議題並開始作出貢獻。導師們會支持幫助並審查他們的貢獻。</p><p>這種方法鼓勵貢獻的多樣性，並歡迎任何人，無論他們的編碼能力如何，都可以在友好和不怕出錯的環境中做出貢獻。</p><h4 id="開源大使" tabindex="-1">開源大使 <a class="header-anchor" href="#開源大使" aria-label="Permalink to “開源大使”">​</a></h4><p>在此計劃中，我們從社區中選擇大使，理想情況下他們將涵蓋我們旨在促進的每一類貢獻。至今該計劃已啓動了兩次。</p><p>該計劃旨在讓成員通過回答社區的議題、協助貢獻者參與併為他們指定的類別宣傳來幫助管理項目和計劃。</p><p>第一個計劃舉行時我們接受了所有的申請者。我們評估了社區成員的興趣所在，併為那些想要做出貢獻但最初不敢踏出第一步的人提供了一個體系。</p><p>第一個計劃的舉辦給了我們很多啓發。因為我們的活動中既有經驗豐富的開源貢獻者和社區成員，也有初來乍到缺乏經驗的新手，因此項目的執行要求管理員進行大量的管理工作。一些社區大使信心十足準備好進一步採取新措施，而其他大使則需要更多支持。到了第二個，我們決定縮減該計劃，只接受那些已經熟悉社區、可以領導倡議和項目並幫助我們培訓新人的貢獻者。</p><p>第二個計劃中形成了正反饋循環。那些在第一個計劃中還是新手的大使們，通過為上一個項目做出貢獻並且從項目經驗中學習之後能夠做到輕鬆帶領項目。</p><p>這種方法的改變使管理員能夠更加專注於支持大使團隊，幫助他們傳播我們的使命，並繼續讓我們的社區對新手友好，並指導更多人做出貢獻。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>這些計劃幫助我們提高了對開源貢獻和回饋的不同方式的認識。通過它們，我們發現志願者通過管理項目和舉辦公開會議來提供幫助，這有助於管理社區併為我們的貢獻者提供指導。</p><p>儘管我們得到了貢獻者的良好反響，並幫助人們做出了他們的第一個貢獻，但我們仍有很大的改進空間。我們將繼續改進我們項目的設置和貢獻指南，以改善貢獻者的體驗。我們還將繼續專注於確保我們的組織始終擁有並推動不同類別的問題，促進包容性，以便任何有意願做出貢獻的人都能出自己的一份力。</p><hr>',13)),r("p",null,[t[33]||(t[33]=l("via: ",-1)),i(n,{href:"https://opensource.com/article/21/8/beginner-open-source-community"},{default:o(()=>[...t[32]||(t[32]=[l("https://opensource.com/article/21/8/beginner-open-source-community",-1)])]),_:1})]),r("p",null,[t[38]||(t[38]=l("作者：",-1)),i(n,{href:"https://opensource.com/users/isabelcmdcosta"},{default:o(()=>[...t[34]||(t[34]=[l("Isabel Costa",-1)])]),_:1}),t[39]||(t[39]=l(" 選題：",-1)),i(n,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[35]||(t[35]=[l("lujun9972",-1)])]),_:1}),t[40]||(t[40]=l(" 譯者：",-1)),i(n,{href:"https://github.com/XiaotingHuang22"},{default:o(()=>[...t[36]||(t[36]=[l("XiaotingHuang22",-1)])]),_:1}),t[41]||(t[41]=l(" 校對：",-1)),i(n,{href:"https://github.com/wxy"},{default:o(()=>[...t[37]||(t[37]=[l("wxy",-1)])]),_:1})]),r("p",null,[t[44]||(t[44]=l("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[42]||(t[42]=[l("LCTT",-1)])]),_:1}),t[45]||(t[45]=l(" 原創編譯，",-1)),i(n,{href:"https://linux.cn/"},{default:o(()=>[...t[43]||(t[43]=[l("Linux中國",-1)])]),_:1}),t[46]||(t[46]=l(" 榮譽推出",-1))])])}const y=s(d,[["render",m]]);export{C as __pageData,y as default};
